use serde::{Deserialize,Serialize}; use super::{digest,error::{AdmissionError,AdmissionErrorKind,Result}};
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq,Hash,Ord,PartialOrd)] pub struct SubjectId{pub repository:String,pub path:String,pub revision:String}
impl SubjectId{pub fn exact(r:impl Into<String>,p:impl Into<String>,v:impl Into<String>)->Self{Self{repository:r.into(),path:p.into(),revision:v.into()}}pub fn key(&self)->String{format!("{}:{}@{}",self.repository,self.path,self.revision)}pub fn digest(&self)->String{digest::digest(&[&self.repository,&self.path,&self.revision])}pub fn validate(&self)->Result<()>{if self.repository.trim().is_empty(){return Err(AdmissionError::new(AdmissionErrorKind::InvalidSubject,"subject.repository.empty","repository is required"))}if self.path.trim().is_empty()||self.path.starts_with('/')||self.path.split('/').any(|p|p==".."||p.is_empty()){return Err(AdmissionError::new(AdmissionErrorKind::InvalidSubject,"subject.path.invalid","path must be repository-relative and normalized").subject(self.key()))}if self.revision.trim().is_empty(){return Err(AdmissionError::new(AdmissionErrorKind::InvalidSubject,"subject.revision.empty","exact revision is required").subject(self.key()))}Ok(())}pub fn same_object(&self,o:&Self)->bool{self.repository==o.repository&&self.path==o.path}pub fn exact_match(&self,o:&Self)->bool{self==o}}